#!/usr/bin/env python3
"""Extract pinned AirCard artwork primitives, excluding backup/general CLI.
Copyright upstream retained. Cleanup hardening does not change archive mechanism.
"""
import ast
from pathlib import Path
src = Path('upstream/AirCard/apply_card_skin.py').read_text()
tree = ast.parse(src)
selected = {'zip_info', 'build_archive', 'build_archive_multi', 'build_books', 'run_json',
            'native', 'operation_ok'}
header = '''# Adapted from AirCard, MIT, copyright (c) 2026 Johnny Franks.
# See bundled AirCard-LICENSE.txt. Generated by scripts/prepare_artwork.py.
import io
import json
import shutil
import os
import plistlib
import posixpath
import secrets
import stat
import struct
import subprocess
import tempfile
import time
import zipfile
from pathlib import Path
ROOT = Path(__file__).resolve().parent
DEVICE_HELPER = ROOT / "bin" / "device_helper"
AIRTRAFFIC_HOST = ROOT / "bin" / "airtraffic_host"
SOURCE_PREFIX = "airlift-src-"
LINK_PREFIX = "airlift-link-"
RECOVERED_PREFIX = "airlift-recovered-"
SZ_EXTRA_ID = 0x5A53
RECOVERY_ROOT = Path.home() / "Library/Application Support/WalletSkin Studio/Recovery"

class PersistentOperation:
    def __init__(self, udid, target, source, link_destination, recovered):
        self.udid, self.target = udid, target
        self.source, self.link_destination, self.recovered = source, link_destination, recovered
        self.path = RECOVERY_ROOT / secrets.token_hex(16)
        self.complete = False
    def __enter__(self):
        os.umask(0o077)
        self.path.mkdir(mode=0o700, parents=True)
        journal = self.path / "pending.json"
        journal.write_text(json.dumps({"deviceID": self.udid, "target": self.target,
                                      "created": time.time(), "source": self.source, "linkDestination": self.link_destination, "recovered": self.recovered, "purpose": "Books staging recovery; not original artwork backup"}))
        journal.chmod(0o600)
        return self
    def __exit__(self, kind, error, traceback):
        if self.complete:
            shutil.rmtree(self.path)
        # Otherwise keep snapshot + staged archive for manual recovery. Never replay.
'''
functions = [ast.get_source_segment(src, node) for node in tree.body if isinstance(node, ast.FunctionDef) and node.name in selected]
hardened = '''
def write_files_batch(udid, target, files, retries=1, progress_callback=None):
    # AirCard's original archive/staging/ATC sequence, with cleanup in finally.
    # One attempt only: interruption must never trigger an automatic repeat.
    if not files:
        return False
    token = secrets.token_hex(10)
    source = SOURCE_PREFIX + token
    link_destination = LINK_PREFIX + token
    recovered = RECOVERED_PREFIX + token
    link_identifier = f"../../{source}/p0/p1/p2/link"
    identifiers = [link_identifier] + [f"../../{source}/payload_{i}" for i in range(len(files))]
    destinations = [link_destination] + [posixpath.join(link_destination, leaf) for leaf, _ in files]
    with PersistentOperation(udid, target, source, link_destination, recovered) as operation:
        work = operation.path
        archive_path, books_path = work / "payload.zip", work / "Books.plist"
        snapshot_root = work / "books-snapshot"
        snapshot_root.mkdir(mode=0o700)
        archive_path.write_bytes(build_archive_multi(target, files))
        books_path.write_bytes(build_books(identifiers))
        archive_path.chmod(0o600)
        books_path.chmod(0o600)
        snapshot = native("snapshot-books", udid, str(snapshot_root))
        if not operation_ok(snapshot):
            operation.complete = True
            return False
        atc_ok, finish_ok = False, False
        cleanup_authorized = None
        try:
            stage = native("stage", udid, source, link_destination, recovered,
                           str(archive_path), str(books_path), str(snapshot_root))
            cleanup_authorized = stage.get("operation", {}).get("cleanupAuthorized")
            if operation_ok(stage) and cleanup_authorized is True:
                command = [str(AIRTRAFFIC_HOST), udid]
                for identifier, destination in zip(identifiers, destinations):
                    command.extend((identifier, destination))
                atc = run_json(command, timeout=max(120, len(files) * 2))
                atc_ok = bool(atc.get("exitCode") == 0 and atc.get("ok"))
        except Exception:
            atc_ok = False
        finally:
            if cleanup_authorized is True:
                try:
                    finish = native("finish-write", udid, source, link_destination,
                                    recovered, str(snapshot_root))
                    finish_ok = operation_ok(finish)
                except Exception:
                    finish_ok = False
            # False means native Stage proved it did not write. Unknown means
            # its outcome is uncertain: preserve the preimage and do not replay
            # or restore Books automatically, which could overwrite newer state.
        operation.complete = finish_ok or cleanup_authorized is False
        return atc_ok and finish_ok

def remove_files_batch(udid, target, leaves, retries=1):
    # Upstream cache unlink sequence; cleanup only after explicit Stage authorization.
    if not leaves or any(leaf not in {"FrontFace", "PlaceHolder", "Preview"} for leaf in leaves):
        return False
    token = secrets.token_hex(10)
    source = SOURCE_PREFIX + token
    link_destination = LINK_PREFIX + token
    recovered = RECOVERED_PREFIX + token
    link_identifier = f"../../{source}/p0/p1/p2/link"
    protected = [f"../../{link_destination}/{leaf}" for leaf in leaves]
    removed = [f"{source}/removed-{i}" for i in range(len(leaves))]
    with PersistentOperation(udid, target, source, link_destination, recovered) as operation:
        work = operation.path
        archive_path, books_path = work / "payload.zip", work / "Books.plist"
        snapshot_root = work / "books-snapshot"
        snapshot_root.mkdir(mode=0o700)
        archive_path.write_bytes(build_archive(target, b"aircard-v2"))
        books_path.write_bytes(build_books([link_identifier, *protected]))
        archive_path.chmod(0o600)
        books_path.chmod(0o600)
        snapshot = native("snapshot-books", udid, str(snapshot_root))
        if not operation_ok(snapshot):
            operation.complete = True
            return False
        atc_ok, finish_ok = False, False
        cleanup_authorized = None
        try:
            stage = native("stage", udid, source, link_destination, recovered,
                           str(archive_path), str(books_path), str(snapshot_root))
            cleanup_authorized = stage.get("operation", {}).get("cleanupAuthorized")
            if operation_ok(stage) and cleanup_authorized is True:
                command = [str(AIRTRAFFIC_HOST), udid, link_identifier, link_destination]
                for identifier, destination in zip(protected, removed):
                    command.extend((identifier, destination))
                atc = run_json(command, timeout=120)
                atc_ok = bool(atc.get("exitCode") == 0 and atc.get("ok"))
        except Exception:
            atc_ok = False
        finally:
            if cleanup_authorized is True:
                try:
                    finish_command = "finish-moved-removal" if atc_ok else "finish-write"
                    args = [str(snapshot_root)] + ([str(len(leaves))] if atc_ok else [])
                    finish = native(finish_command, udid, source, link_destination, recovered, *args)
                    finish_ok = operation_ok(finish)
                except Exception:
                    finish_ok = False
        operation.complete = finish_ok or cleanup_authorized is False
        return atc_ok and finish_ok
'''
# No retry/fallback cache loops: a failed batch must stop further staging.
hardened += """
def remove_files(udid, target, leaves, retries=1):
    return remove_files_batch(udid, target, leaves, retries=1)

def invalidate_cache(udid, card_hash):
    for extension in (".cache", ".pkcache"):
        target = f"/var/mobile/Library/Passes/Cards/{card_hash}{extension}"
        if not remove_files_batch(udid, target, ["FrontFace", "PlaceHolder", "Preview"], retries=1):
            return False
    return True
"""
assets = Path('upstream/AirCard/card_assets.py').read_text()
assets_tree = ast.parse(assets)
asset_function = next(ast.get_source_segment(assets, node) for node in assets_tree.body if isinstance(node, ast.FunctionDef) and node.name == 'build_card_assets')
asset_function = asset_function.replace('stderr=subprocess.PIPE,', 'stderr=subprocess.DEVNULL, timeout=30,')
asset_function = asset_function.replace('png_path.write_bytes(png_bytes)', 'png_path.write_bytes(png_bytes)\n        png_path.chmod(0o600)')
asset_function = asset_function.replace('pdf_bytes = pdf_path.read_bytes()', 'pdf_bytes = pdf_path.read_bytes()\n        if not pdf_bytes.startswith(b"%PDF-") or len(pdf_bytes) > 32*1024*1024:\n            raise RuntimeError("invalid_prepared_pdf")')
asset_constants = '\nPNG_ASSET_NAMES = ("cardBackgroundCombined@3x.png", "cardBackgroundCombined@2x.png")\nPDF_ASSET_NAME = "cardBackgroundCombined.pdf"\n'
content = header + '\n\n'.join(functions) + hardened + asset_constants + asset_function
content = content.replace('def remove_files(udid: str, target: str, leaves: list[str], retries: int = 3)', 'def remove_files(udid: str, target: str, leaves: list[str], retries: int = 1)')
Path('Resources/aircard_artwork.py').write_text(content)
